--
-- Name: bump_item_version(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bump_item_version(p_item_code text, p_item_type text) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_type text := TRIM(p_item_type);
    v_code text := public.normalize_item_version_code(p_item_code, v_type);
    v_version integer;
BEGIN
    IF v_code IS NULL OR v_code = '' THEN
        RAISE EXCEPTION 'item_code is required';
    END IF;
    IF v_type IS NULL OR v_type NOT IN ('dishes', 'raw_materials_cost', 'scoop_config') THEN
        RAISE EXCEPTION 'item_type must be dishes, raw_materials_cost, or scoop_config';
    END IF;

    VALUES (v_code, v_type, 1)
    ON CONFLICT (item_code, item_type)
    DO UPDATE SET
        version = public.item_versions.version + 1,
        last_updated_at = CURRENT_TIMESTAMP
    RETURNING version INTO v_version;

    RETURN v_version;
END;
$$;


--
-- Name: normalize_item_version_code(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_item_version_code(p_item_code text, p_item_type text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    v_type text := TRIM(p_item_type);
    v_code text := TRIM(p_item_code);
BEGIN
    IF v_code IS NULL OR v_code = '' THEN
        RETURN NULL;
    END IF;
    IF v_type = 'scoop_config' THEN
        RETURN LOWER(v_code);
    END IF;
    RETURN UPPER(v_code);
END;
$$;


--
-- Name: touch_last_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.touch_last_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.last_updated_at = CURRENT_TIMESTAMP;
  RETURN NEW;
END;
$$;


